using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Net;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.ServiceProcess;
using System.Web.Script.Serialization;
using Microsoft.Win32;
[assembly:System.Reflection.AssemblyVersion("0.2.0.0")]
namespace ContourWatch {
public class Agent : ServiceBase {
 public const string Version="0.2.0";
 public static JavaScriptSerializer Json { get { return new JavaScriptSerializer { MaxJsonLength=1048576,RecursionLimit=100 }; } }
 public static string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"ContourWatch");
 Thread worker; readonly ManualResetEvent stop=new ManualResetEvent(false);
 public Agent(){ServiceName="ContourWatch";CanStop=true;AutoLog=false;}
 public static void ConfigureTls(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;}
 public static void CheckConnection(string server){ConfigureTls();var request=(HttpWebRequest)WebRequest.Create(Endpoint(server,"/health",false));request.Timeout=12000;request.ReadWriteTimeout=12000;request.AllowAutoRedirect=false;request.Proxy=null;using(var response=(HttpWebResponse)request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){var data=Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());if(response.StatusCode!=HttpStatusCode.OK||!data.ContainsKey("ok")||!Convert.ToBoolean(data["ok"]))throw new IOException("API не подтвердил готовность");}}
 public static void ConfigureConsoleEncoding(){try{Console.OutputEncoding=new UTF8Encoding(false);}catch(IOException){}catch(System.Security.SecurityException){}}
 public static int Main(string[] args){try{if(args.Length>0)ConfigureConsoleEncoding();if(args.Contains("--test-sleep")){Thread.Sleep(30000);return 0;}ConfigureTls();
  if(args.Length>0&&args[0]=="--test-config"){Root=Path.GetFullPath(args[1]);Directory.CreateDirectory(Root);Endpoint(args[2],"/health",true);SaveConfig(Obj("server",args[2],"token",Protect(Environment.GetEnvironmentVariable("CW_TEST_TOKEN")),"localTest",true,"name","E2E-WINDOWS","group","Test"));return 0;}
  if(args.Length==2&&args[0]=="--diagnostics"){DiagnosticExport.Write(args[1]);Console.WriteLine("Диагностический архив создан; проверьте содержимое перед передачей.");return 0;}
  if(args.Length>0&&args[0]=="--collect"){Console.Write(Json.Serialize(Collectors.Read(args[1])));return 0;}
  if(args.Length>0&&args[0]=="--self-test")return SelfTest();
  if(args.Length>1&&args[0]=="--root")Root=Path.GetFullPath(args[1]);
  if(args.Contains("--once")){Directory.CreateDirectory(Root);var a=new Agent();a.Cycle(true);return 0;}
  if(args.Contains("--console")){var a=new Agent();Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;a.stop.Set();};a.Loop();return 0;}
  ServiceBase.Run(new Agent());return 0;
 }catch(Exception e){try{Directory.CreateDirectory(Root);Log("startup "+e.GetType().Name+": "+e.Message);}catch{}try{Console.Error.WriteLine(e.GetType().Name+": "+e.Message);}catch{}return 1;}}
 protected override void OnStart(string[] args){worker=new Thread(()=>{try{string sc=Path.Combine(Environment.SystemDirectory,"sc.exe");Run(sc,"failure ContourWatch reset= 86400 actions= restart/10000/restart/30000/restart/60000",3000);Run(sc,"failureflag ContourWatch 1",3000);}catch(Exception e){AgentLog.Write("warning","service","recovery.configure.failed",e.GetType().Name);}Loop();}){IsBackground=true};worker.Start();}
 protected override void OnStop(){stop.Set();if(worker!=null)worker.Join(5000);}
 public static string Iso(){return DateTime.UtcNow.ToString("o");}
 public static Dictionary<string,object> Obj(params object[] a){var d=new Dictionary<string,object>();for(int i=0;i<a.Length;i+=2)d[(string)a[i]]=a[i+1];return d;}
 public static string Get(Dictionary<string,object> d,string k,string fallback=""){return d.ContainsKey(k)&&d[k]!=null?Convert.ToString(d[k]):fallback;}
 public static void Atomic(string path,string data){string tmp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(tmp,data,new UTF8Encoding(false));if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 public static Dictionary<string,object> Config(){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Root,"config.json")));}
 public static void SaveConfig(Dictionary<string,object> c){Atomic(Path.Combine(Root,"config.json"),Json.Serialize(c));}
 public static string Protect(string s){return Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(s),null,DataProtectionScope.LocalMachine));}
 public static string Unprotect(string s){return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(s),null,DataProtectionScope.LocalMachine));}
 public static Uri Endpoint(string server,string path,bool local){Uri u;if(!Uri.TryCreate(server,UriKind.Absolute,out u)||!String.IsNullOrEmpty(u.UserInfo)||u.AbsolutePath!="/"||!String.IsNullOrEmpty(u.Query)||!String.IsNullOrEmpty(u.Fragment)||(u.Scheme!="https"&&!(local&&u.Scheme=="http"&&u.IsLoopback)))throw new ArgumentException("Нужен HTTPS адрес сервера без пути и учётных данных");return new Uri(u,path);}
 public static Dictionary<string,object> Post(Dictionary<string,object> c,string path,object body){ConfigureTls();var uri=Endpoint(Get(c,"server"),path,Get(c,"localTest")=="True");var r=(HttpWebRequest)WebRequest.Create(uri);r.Method="POST";r.ContentType="application/json";r.Timeout=12000;r.ReadWriteTimeout=12000;r.AllowAutoRedirect=false;r.Proxy=null;
  if(c.ContainsKey("secret")){r.Headers["X-Device-Id"]=Get(c,"id");r.Headers["Authorization"]="Bearer "+Unprotect(Get(c,"secret"));}
  byte[] bytes=Encoding.UTF8.GetBytes(Json.Serialize(body));r.ContentLength=bytes.Length;using(var s=r.GetRequestStream())s.Write(bytes,0,bytes.Length);using(var response=(HttpWebResponse)r.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}
 public static string Run(string exe,string args,int timeout,int max=700000){var p=new Process{StartInfo=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8}};
  using(p){p.Start();var output=Task.Factory.StartNew(()=>Capture(p.StandardOutput,max));var errors=Task.Factory.StartNew(()=>Capture(p.StandardError,32000));if(!p.WaitForExit(timeout)){try{p.Kill();}catch{}p.WaitForExit(1000);throw new System.TimeoutException("collector timeout");}if(!Task.WaitAll(new Task[]{output,errors},2000))throw new System.TimeoutException("output timeout");if(p.ExitCode!=0&&String.IsNullOrWhiteSpace(output.Result))throw new IOException("collector exit code "+p.ExitCode);return output.Result;}}
 static string Capture(StreamReader r,int max){var b=new StringBuilder();var buf=new char[4096];int n;while((n=r.Read(buf,0,buf.Length))>0){if(b.Length+n>max)throw new IOException("collector output limit");b.Append(buf,0,n);}return b.ToString();}
 public static void Log(string text){AgentLog.Write("warning","agent","diagnostic",text);}

 Dictionary<string,List<Dictionary<string,object>>> cache=new Dictionary<string,List<Dictionary<string,object>>>();
 Dictionary<string,DateTime> due=new Dictionary<string,DateTime>();Dictionary<string,Task<List<Dictionary<string,object>>>> jobs=new Dictionary<string,Task<List<Dictionary<string,object>>>>();
 Dictionary<string,object> settings=new Dictionary<string,object>();DateTime nextSend=DateTime.MinValue,nextDelivery=DateTime.MinValue;int failures;bool extendedMetrics,diskWear,paused;DateTime nextControl=DateTime.MinValue;DateTime lastSuccess=DateTime.MinValue;
 int Interval(string kind){string key=kind=="volume"?"volumeSeconds":kind=="smart"?"smartSeconds":"fastSeconds";int fallback=kind=="volume"?300:kind=="smart"?900:60,v;return settings.ContainsKey(key)&&Int32.TryParse(Convert.ToString(settings[key]),out v)?Math.Max(kind=="smart"?300:30,Math.Min(86400,v)):fallback;}
 void Loop(){Directory.CreateDirectory(Root);Directory.CreateDirectory(Path.Combine(Root,"public"));Directory.CreateDirectory(Path.Combine(Root,"queue"));while(!stop.WaitOne(0)){try{Cycle(false);}catch(Exception e){Log("cycle "+e.GetType().Name);}stop.WaitOne(1000);}}
 void PollControl(){if(DateTime.UtcNow<nextControl)return;nextControl=DateTime.UtcNow.AddSeconds(30);try{var c=Config();if(!c.ContainsKey("secret"))return;var r=Post(c,"/api/control",Obj("version",Version,"paused",paused&&jobs.Values.All(j=>j.IsCompleted)));bool next=r.ContainsKey("paused")&&Convert.ToBoolean(r["paused"]);if(next!=paused){cache.Clear();due.Clear();}paused=next;if(r.ContainsKey("settings"))settings=(Dictionary<string,object>)r["settings"];if(r.ContainsKey("capabilities")){var caps=(Dictionary<string,object>)r["capabilities"];extendedMetrics=caps.ContainsKey("extendedSensors")&&Convert.ToBoolean(caps["extendedSensors"]);diskWear=caps.ContainsKey("diskWear")&&Convert.ToBoolean(caps["diskWear"]);}if(r.ContainsKey("updates"))AgentUpdater.Poll(c,(Dictionary<string,object>)r["updates"]);lastSuccess=DateTime.UtcNow;if(paused)Atomic(Path.Combine(Root,"public","status.json"),Json.Serialize(Obj("version",Version,"state","На паузе","lastSuccess",Iso(),"queue",Directory.GetFiles(Path.Combine(Root,"queue"),"*.json").Length,"server",Get(c,"server"))));}catch(WebException e){var response=e.Response as HttpWebResponse;if(response!=null&&response.StatusCode==HttpStatusCode.NotFound)nextControl=DateTime.UtcNow.AddMinutes(5);if(response!=null)response.Dispose();}catch(Exception e){AgentLog.Transition("control",e.GetType().Name,"Служебная связь временно недоступна");}}
 void Cycle(bool once){
  if(!once&&!File.Exists(Path.Combine(Root,"config.json"))){if(DateTime.UtcNow>=nextSend){Atomic(Path.Combine(Root,"public","status.json"),Json.Serialize(Obj("version",Version,"state","Ожидается настройка сервера","queue",0)));nextSend=DateTime.UtcNow.AddSeconds(30);}return;}
  if(!once){PollControl();if(paused){foreach(var k in jobs.Where(j=>j.Value.IsCompleted).Select(j=>j.Key).ToArray())jobs.Remove(k);return;}}

  foreach(string kind in new[]{"ram","volume","sensors","gpu","smart"}){
   if(once){try{cache[kind]=Collect(kind);}catch(Exception e){cache[kind]=new List<Dictionary<string,object>>{Collectors.Metric(kind+":collector",kind=="sensors"||kind=="gpu"?"collector":kind,kind,"error",null,"",Agent.Obj("errorType",e.GetType().Name,"message",AgentLog.Clean(e.Message)))};}continue;}
   Task<List<Dictionary<string,object>>> job;if(jobs.TryGetValue(kind,out job)&&job.IsCompleted){if(job.Status==TaskStatus.RanToCompletion)cache[kind]=job.Result;else cache[kind]=new List<Dictionary<string,object>>{Collectors.Metric(kind+":collector",kind=="sensors"||kind=="gpu"?"collector":kind,kind,"error",null,"","timeout / collector error")};AgentLog.Transition("collector."+kind,cache[kind].Any(m=>Get(m,"state")!="ok")?"degraded":"ok","Результат сбора: "+kind);jobs.Remove(kind);due[kind]=DateTime.UtcNow.AddSeconds(Interval(kind));}
   if(!jobs.ContainsKey(kind)&&(!due.ContainsKey(kind)||due[kind]<=DateTime.UtcNow)){string k=kind;jobs[kind]=Task.Factory.StartNew(()=>Collect(k));}
  }
  if(once||DateTime.UtcNow>=nextSend){var metrics=cache.Values.SelectMany(m=>m).Where(m=>(Get(m,"kind")!="disk_wear"||diskWear)&&(extendedMetrics||!new[]{"gpu_temperature","gpu_load","gpu_fan","gpu_memory_used","gpu_memory_total","cpu_load"}.Contains(Get(m,"kind")))).ToList();if(metrics.Count>0){var payload=Obj("batchId",Guid.NewGuid().ToString(),"measuredAt",Iso(),"version",Version,"metrics",metrics,"diagnostics",AgentLog.Snapshot(),"hardware",Obj("architecture",Environment.Is64BitOperatingSystem?"x64":"x86","virtual",Collectors.IsVirtual(),"cpu",Collectors.CpuName()),"updateStatus",AgentUpdater.Status);Enqueue(Json.Serialize(payload));nextSend=DateTime.UtcNow.AddSeconds(Interval("ram"));}}
  if(once){Console.WriteLine("Собрано: "+cache.Values.Sum(m=>m.Count)+" метрик. Каталог: "+Root);return;}
  if(DateTime.UtcNow<nextDelivery)return;
  try{var c=Config();if(!c.ContainsKey("secret")){if(!c.ContainsKey("requestId")){c["requestId"]=Guid.NewGuid().ToString();var bytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(bytes);c["deviceSecret"]=Protect(Convert.ToBase64String(bytes).TrimEnd('=').Replace('+','-').Replace('/','_'));SaveConfig(c);}var response=Post(c,"/api/register",Obj("token",Unprotect(Get(c,"token")),"name",Get(c,"name",Environment.MachineName),"group",Get(c,"group","Без группы"),"os",Collectors.OS(),"version",Version,"requestId",Get(c,"requestId"),"deviceSecret",Unprotect(Get(c,"deviceSecret"))));lastSuccess=DateTime.UtcNow;c["id"]=response["id"];c["secret"]=Protect(Convert.ToString(response["secret"]));c.Remove("token");c.Remove("requestId");c.Remove("deviceSecret");SaveConfig(c);}
   int sent=0;foreach(var file in Directory.GetFiles(Path.Combine(Root,"queue"),"*.json").OrderBy(x=>x).Take(20)){Dictionary<string,object> p;try{p=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));}catch{File.Delete(file);Log("corrupt queue entry removed");continue;}if(DateTime.Parse(Get(p,"measuredAt"),null,System.Globalization.DateTimeStyles.RoundtripKind).ToUniversalTime()<DateTime.UtcNow.AddDays(-7)){File.Delete(file);continue;}var reply=Post(c,"/api/ingest",p);if(reply.ContainsKey("paused")&&Convert.ToBoolean(reply["paused"])){paused=true;return;}lastSuccess=DateTime.UtcNow;if(reply.ContainsKey("capabilities")){var caps=reply["capabilities"] as Dictionary<string,object>;extendedMetrics=caps!=null&&caps.ContainsKey("extendedSensors")&&Convert.ToBoolean(caps["extendedSensors"]);diskWear=caps!=null&&caps.ContainsKey("diskWear")&&Convert.ToBoolean(caps["diskWear"]);}if(reply.ContainsKey("settings"))settings=(Dictionary<string,object>)reply["settings"];File.Delete(file);sent++;}
   if(sent>0)AgentLog.Transition("delivery","ok","Пакеты успешно доставлены");failures=0;nextDelivery=DateTime.UtcNow.AddSeconds(2);Atomic(Path.Combine(Root,"public","status.json"),Json.Serialize(Obj("version",Version,"state","В сети","lastSuccess",lastSuccess==DateTime.MinValue?null:(object)lastSuccess.ToString("o"),"queue",Directory.GetFiles(Path.Combine(Root,"queue"),"*.json").Length,"server",Get(c,"server"))));
  }catch(Exception e){failures=Math.Min(failures+1,12);nextDelivery=DateTime.UtcNow.AddSeconds(Math.Min(300,Math.Pow(2,failures))+new Random().Next(1,10));string diagnostic=DeliveryError(e);AgentLog.Transition("delivery",diagnostic,diagnostic);AgentLog.Write("warning","delivery","retry.scheduled",diagnostic,"retrySeconds",Math.Max(0,(int)(nextDelivery-DateTime.UtcNow).TotalSeconds),"queue",Directory.GetFiles(Path.Combine(Root,"queue"),"*.json").Length);Atomic(Path.Combine(Root,"public","status.json"),Json.Serialize(Obj("version",Version,"state","Нет связи / ошибка конфигурации","error",diagnostic,"lastAttempt",Iso(),"queue",Directory.GetFiles(Path.Combine(Root,"queue"),"*.json").Length)));}
 }
 public static string DeliveryError(Exception e){var web=e as WebException;if(web==null)return "Ошибка передачи: "+e.GetType().Name;var response=web.Response as HttpWebResponse;if(response!=null){int code=(int)response.StatusCode;response.Dispose();return "HTTP "+code+": "+(code==403?"доступ запрещён; проверьте токен регистрации и правила прокси":code==401?"учётные данные устройства отклонены":code==429?"лимит запросов, повтор будет позже":code==502||code==503?"сервер за прокси недоступен":"запрос отклонён API");}return web.Status==WebExceptionStatus.TrustFailure?"TLS: сертификат не прошёл проверку доверия":web.Status==WebExceptionStatus.SecureChannelFailure?"TLS: не удалось создать защищённый канал":web.Status==WebExceptionStatus.NameResolutionFailure?"DNS: имя сервера не найдено":web.Status==WebExceptionStatus.Timeout?"Тайм-аут связи с сервером":"Ошибка связи: "+web.Status;}
 public static List<Dictionary<string,object>> Collect(string kind){var output=Run(System.Reflection.Assembly.GetExecutingAssembly().Location,"--collect "+kind,25000);return Json.Deserialize<List<Dictionary<string,object>>>(output);}
 public static void Enqueue(string payload){if(Encoding.UTF8.GetByteCount(payload)>950000){Log("sample exceeds size limit");return;}string q=Path.Combine(Root,"queue");Directory.CreateDirectory(q);Atomic(Path.Combine(q,DateTime.UtcNow.ToString("yyyyMMddHHmmssfff")+"-"+Guid.NewGuid().ToString("N")+".json"),payload);var files=new DirectoryInfo(q).GetFiles("*.json").OrderBy(f=>f.Name).ToList();long size=files.Sum(f=>f.Length);while(files.Count>1500||size>50*1024*1024){var f=files[0];size-=f.Length;f.Delete();files.RemoveAt(0);Log("queue limit: oldest sample dropped");}}
 static int SelfTest(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("FAIL "+name);n++;Console.WriteLine("PASS "+name);};check(Endpoint("https://server.local","/health",false).Scheme=="https","HTTPS");foreach(var x in new[]{"http://server.local","https://u:p@server.local","https://server.local/path","https://server.local?x=1","file:///C:/"}){bool rejected=false;try{Endpoint(x,"/health",false);}catch{rejected=true;}check(rejected,"URL rejection");}check(Unprotect(Protect("test-secret"))=="test-secret","DPAPI roundtrip");var m=Collectors.Read("ram");check(m.Count>0&&m[0]["state"].ToString()=="ok","physical RAM");check(Convert.ToDouble(m[0]["value"])>=0&&Convert.ToDouble(m[0]["value"])<=100,"RAM range");check(Collectors.Read("volume").Count>0,"volumes");bool timeout=false;try{Run(System.Reflection.Assembly.GetExecutingAssembly().Location,"--test-sleep",100);}catch(System.TimeoutException){timeout=true;}check(timeout,"process timeout");check(Collectors.RiskAttributes(Json.Deserialize<Dictionary<string,object>>(@"{""ata_smart_attributes"":{""table"":[{""id"":197,""raw"":{""value"":2}}]}}")),"ATA pending sector risk");check(Collectors.RiskAttributes(Json.Deserialize<Dictionary<string,object>>(@"{""nvme_smart_health_information_log"":{""critical_warning"":1}}")),"NVMe critical warning");check(!Collectors.RiskAttributes(new Dictionary<string,object>()),"Unknown SMART is not fabricated risk");Console.WriteLine(n+" checks passed");return 0;}
}
public static class Collectors {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Auto)]class Memory {public uint length=(uint)Marshal.SizeOf(typeof(Memory));public uint load;public ulong total,available,totalPage,availPage,totalVirtual,availVirtual,extended;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GlobalMemoryStatusEx([In,Out]Memory data);
 public static Dictionary<string,object> Metric(string id,string kind,string name,string state,object value,string unit,object details){return Agent.Obj("id",id,"kind",kind,"name",name,"state",state,"value",value,"unit",unit,"source",kind=="smart"||kind=="disk_wear"?"smartctl":kind=="temperature"||kind=="fan"?"LibreHardwareMonitor":"Windows","measuredAt",Agent.Iso(),"details",details);}
 public static string OS(){using(var k=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion")){return k==null?Environment.OSVersion.ToString():Convert.ToString(k.GetValue("ProductName"))+" build "+Convert.ToString(k.GetValue("CurrentBuildNumber"));}}
 public static string CpuName(){try{using(var key=Registry.LocalMachine.OpenSubKey(@"HARDWARE\DESCRIPTION\System\CentralProcessor\0"))return Convert.ToString(key.GetValue("ProcessorNameString")).Trim();}catch{return "Не определён";}}
 public static bool IsVirtual(){try{using(var k=Registry.LocalMachine.OpenSubKey(@"HARDWARE\DESCRIPTION\System\BIOS")){string s=Convert.ToString(k.GetValue("SystemManufacturer"))+" "+Convert.ToString(k.GetValue("SystemProductName"));return new[]{"virtual","vmware","qemu","kvm","xen"}.Any(v=>s.ToLowerInvariant().Contains(v));}}catch{return false;}}
 public static List<Dictionary<string,object>> Read(string kind){var result=new List<Dictionary<string,object>>();try{
 if(kind=="ram"){var m=new Memory();if(!GlobalMemoryStatusEx(m)||m.total==0)throw new IOException();result.Add(Metric("ram","ram","Физическая память","ok",(m.total-m.available)*100.0/m.total,"%",Agent.Obj("totalBytes",m.total,"availableBytes",m.available,"usedBytes",m.total-m.available)));}
 else if(kind=="volume"){foreach(var d in DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed)){try{long total=d.TotalSize,free=d.TotalFreeSpace;if(total<=0)continue;result.Add(Metric("volume:"+d.Name,"volume",d.Name,"ok",(total-free)*100.0/total,"%",Agent.Obj("totalBytes",total,"freeBytes",free,"usedBytes",total-free)));}catch(UnauthorizedAccessException){result.Add(Metric("volume:"+d.Name,"volume",d.Name,"denied",null,"%",null));}catch{result.Add(Metric("volume:"+d.Name,"volume",d.Name,"error",null,"%",null));}}}
 else if(kind=="sensors")ReadSensors(result);
 else if(kind=="gpu")result.AddRange(NvidiaCollector.Read());
 else if(kind=="smart")result.AddRange(SmartCollector.Read());
 }catch(UnauthorizedAccessException){result.Add(Metric(kind+":collector",kind=="sensors"||kind=="gpu"?"collector":kind,kind,"denied",null,"",null));}catch(Exception e){result.Add(Metric(kind+":collector",kind=="sensors"||kind=="gpu"?"collector":kind,kind,"error",null,"",Agent.Obj("errorType",e.GetType().Name,"message",AgentLog.Clean(e.Message))));}return result;}
 static void ReadSensors(List<Dictionary<string,object>> list){string worker=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ContourSensorWorker.exe");if(!File.Exists(worker)){list.Add(Metric("sensors:missing","collector","Аппаратный сборщик","unsupported",null,"",Agent.Obj("reason","Обновите установщик: отсутствует аппаратный сборщик")));return;}list.AddRange(Agent.Json.Deserialize<List<Dictionary<string,object>>>(Agent.Run(worker,"",22000)));}
public static bool RiskAttributes(Dictionary<string,object> raw){
 if(raw.ContainsKey("nvme_smart_health_information_log")){var n=(Dictionary<string,object>)raw["nvme_smart_health_information_log"];foreach(string key in new[]{"critical_warning","media_errors"})if(n.ContainsKey(key)&&Convert.ToDouble(n[key])>0)return true;if(n.ContainsKey("percentage_used")&&Convert.ToDouble(n["percentage_used"])>=100)return true;}
 if(raw.ContainsKey("scsi_grown_defect_list")&&Convert.ToDouble(raw["scsi_grown_defect_list"])>0)return true;
 if(raw.ContainsKey("ata_smart_attributes")){var attrs=(Dictionary<string,object>)raw["ata_smart_attributes"];if(attrs.ContainsKey("table"))foreach(Dictionary<string,object> row in (IEnumerable)attrs["table"]){int id=Convert.ToInt32(row["id"]);if(id!=5&&id!=197&&id!=198)continue;if(row.ContainsKey("raw")){var value=(Dictionary<string,object>)row["raw"];if(value.ContainsKey("value")&&Convert.ToDouble(value["value"])>0)return true;}}}return false;
}
 public static Dictionary<string,object> SmartDetails(Dictionary<string,object> raw){var details=Agent.Obj("model",Agent.Get(raw,"model_name"),"serial",Agent.Get(raw,"serial_number"),"raw",raw);return details;}
}
}






